void Solver::bump_var(int var, double coeff) {
    // Exponential moving average with momentum
    double delta = var_inc * coeff;
    activity[var] += delta;
    // Apply momentum to variable increment
    var_inc *= 1.05;

    if (activity[var] > 1e100) {
        // Rescale activities to prevent overflow
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }

    // Update heap if variable is present
    if (vsids.inHeap(var)) vsids.update(var);
}
